/* Jukebox Interface*/
static void UserApp1SM_Idle(void)
{
  static u8 *list_of_songs[20] = {"Overworld", "Underwater", "Zelda", "Tetris"};
  static void (*song[])(void) = {Overworld, Underwater, Zelda, Tetris};
  static u8 song_index = 0;
  static u8 num_songs = 4;
  shuffling = TRUE;

  LcdCommand(LCD_HOME_CMD);
  LcdMessage(LINE1_START_ADDR, list_of_songs[song_index]);

  if(WasButtonPressed(BUTTON0)) 
  {
    ButtonAcknowledge(BUTTON0);
    shuffling = FALSE;
    UserApp1_pfStateMachine = song[song_index];
  }

  if(WasButtonPressed(BUTTON1) || shuffling) 
  {
    ButtonAcknowledge(BUTTON1);
    if(!shuffling)
      shuffling = TRUE;
    // else                     // Ideally I find a way to make the system pause here for a bit between songs
    // SystemSleep();
    UserApp1_pfStateMachine = song[G_u32SystemTime1s % num_songs];
  }

  if(WasButtonPressed(BUTTON2)) 
  {
    ButtonAcknowledge(BUTTON2);
    shuffling = FALSE;
    if (song_index > 0)
    {
      song_index--;
      LcdCommand(LCD_CLEAR_CMD);
    }
  }

  if(WasButtonPressed(BUTTON3)) 
  {
    ButtonAcknowledge(BUTTON3);
    if(song_index < num_songs)
    {
      song_index++;
      LcdCommand(LCD_CLEAR_CMD);
    }
  }

} /* end UserApp1SM_Idle() */

